200:     /**
201:      * @notice Transfer a single Deposit, conforming to the ERC1155 standard.
202:      * @param sender Source of Deposit.
203:      * @param recipient Destination of Deposit.
204:      * @param depositId ID of Deposit to Transfer.
205:      * @param amount Amount of `token` to Transfer.
206:      *
207:      * @dev the depositID is the token address and stem of a deposit,
208:      * concatinated into a single uint256.
209:      *
210:      */
211:     function safeTransferFrom(
212:         address sender,
213:         address recipient,
214:         uint256 depositId,
215:         uint256 amount,
216:         bytes calldata
217:     ) external fundsSafu noNetFlow noSupplyChange {
218:         require(recipient != address(0), "ERC1155: transfer to the zero address");
219:         // allowance requirements are checked in transferDeposit
220:         (address token, int96 cumulativeGrownStalkPerBDV) = LibBytes.unpackAddressAndStem(
221:             depositId
222:         );
223:         transferDeposit(sender, recipient, token, cumulativeGrownStalkPerBDV, amount);
224:     }
