226:     /**
227:      * @notice Transfer a multiple Deposits, conforming to the ERC1155 standard.
228:      * @param sender Source of Deposit.
229:      * @param recipient Destination of Deposit.
230:      * @param depositIds list of ID of deposits to Transfer.
231:      * @param amounts list of amounts of `token` to Transfer.
232:      *
233:      * @dev {transferDeposits} can be used to transfer multiple deposits, but only
234:      * if they are all of the same token. Since the ERC1155 standard requires the abilty
235:      * to transfer any set of depositIDs, the {transferDeposits} function cannot be used here.
236:      */
237:     function safeBatchTransferFrom(
238:         address sender,
239:         address recipient,
240:         uint256[] calldata depositIds,
241:         uint256[] calldata amounts,
242:         bytes calldata
243:     ) external fundsSafu noNetFlow noSupplyChange {
244:         require(
245:             depositIds.length == amounts.length,
246:             "Silo: depositIDs and amounts arrays must be the same length"
247:         );
248:         require(recipient != address(0), "ERC1155: transfer to the zero address");
249:         // allowance requirements are checked in transferDeposit
250:         address token;
251:         int96 stem;
252:         for (uint i; i < depositIds.length; ++i) {
253:             (token, stem) = LibBytes.unpackAddressAndStem(depositIds[i]);
254:             transferDeposit(sender, recipient, token, stem, amounts[i]);
255:         }
256:     }
257: }
